def sha(b):return hashlib.sha256(b).hexdigest()
def audit(x,o):
 if not o or not o.get('observed'):return {'observed':False,'assignmentCount':None,'maxBound':None,'capacityFeasible':None,'feasibleAssignments':[],'violations':[]}
 # Independent closed assignment enumeration, not first-fit. Untrusted pair only bounded before use.
 assert isinstance(x,dict) and isinstance(x['pods'],list) and 1<=len(x['pods'])<=3
 assert len(set(p['id'] for p in x['pods']))==len(x['pods'])
 capacities={'nodeA':(4,4),'nodeB':(4,2)};demand={p['id']:(p['cpu']+x['overhead']['cpu'],p['memory']+x['overhead']['memory']) for p in x['pods']};ids=[p['id'] for p in x['pods']]
 feasible=[]
 for assignment in itertools.product(('nodeA','nodeB',None),repeat=len(ids)):
  fits=all(sum(demand[pid][axis] for pid,n in zip(ids,assignment) if n==node)<=cap[axis] for node,cap in capacities.items() for axis in (0,1))
  if fits:feasible.append({'assignment':list(assignment),'bound':sum(n is not None for n in assignment)})
 observed=[p['node'] for p in o['placements']];assert [p['pod'] for p in o['placements']]==ids
 violations=[];remaining={}
 for node,cap in capacities.items():
  used=[sum(demand[pid][axis] for pid,n in zip(ids,observed) if n==node) for axis in (0,1)];remaining[node]={'cpu':cap[0]-used[0],'memory':cap[1]-used[1]}
  for axis,k in enumerate(('cpu','memory')):
   if used[axis]>cap[axis]:violations.append({'node':node,'resource':k,'used':used[axis],'capacity':cap[axis]})
 assert o['remaining']==remaining
 capacityFeasible=observed in [f['assignment'] for f in feasible]
 return {'observed':True,'assignmentCount':3**len(ids),'maxBound':max(f['bound'] for f in feasible),'capacityFeasible':capacityFeasible,'feasibleAssignments':feasible,'violations':violations}
def check(root=R):
 run=root/(root/'CURRENT').read_text().strip();d=json.loads((run/'result.json').read_text());assert (run/'stdout.json').read_bytes()==(run/'result.json').read_bytes()
 assert json.loads((root/'requests.json').read_text())==REQUESTS
 oracle=json.loads((root/'oracle.json').read_text());assert oracle['requests']==REQUESTS and oracle['expected']==EXPECTED
 for n,h in d['sourceHashes'].items():assert sha((root/n).read_bytes())==h,n
 for n,v in json.loads((run/'artifacts.json').read_text())['files'].items():
  b=(run/n).read_bytes();assert sha(b)==v['sha256'] and len(b)==v['bytes'],n
 assert [c['id'] for c in d['cases']]==list(REQUESTS)
 for c in d['cases']:
  n=c['id'];x=REQUESTS[n];folder=run/n;inp=x['rawInput'].encode() if 'rawInput' in x else (json.dumps(x,sort_keys=True)+'\n').encode()
  assert (folder/'input.txt').read_bytes()==inp and sha(inp)==c['inputSha256'];assert (folder/'stdout.txt').read_text()==c['stdout'] and (folder/'stderr.txt').read_text()==c['stderr'] and json.loads((folder/'command.json').read_text())==c
  assert c['argv']==['python3','-B','../model.py'] and c['startedUtc']<=c['endedUtc']
  if n=='execution-failure':assert c['exitCode']==3 and c['stdout']=='' and c['stderr'].startswith('JSONDecodeError:') and c['observation'] is None and c['outcome']=='EXECUTION_FAILURE'
  else:
   assert c['stderr']=='' and json.loads(c['stdout'])==c['observation']==EXPECTED[n],n
   assert c['exitCode']==(2 if n.startswith('refused-') else 0) and c['outcome']==('REFUSED' if n.startswith('refused-') else 'OBSERVED')
  au=json.loads((folder/'audit-command.json').read_text());assert au['exitCode']==0 and au['stderr']=='' and au['argv']==['python3','-B','../checker.py','--audit'];assert json.loads(au['stdout'])==c['audit']==audit(x,c['observation']);assert (folder/'audit-stdout.txt').read_text()==au['stdout'];assert (folder/'audit-input.txt').read_text()==au['stdin'];assert json.loads(au['stdin'])=={'request':x,'observation':c['observation']}
  if n=='ignore-memory-fault':assert c['audit']['capacityFeasible'] is False and c['audit']['violations']==[{'node':'nodeA','resource':'memory','used':6,'capacity':4}]
  elif n in EXPECTED and EXPECTED[n] and EXPECTED[n]['observed']:assert c['audit']['capacityFeasible'] is True
  if n=='greedy-trap':assert c['audit']['maxBound']==2 and c['observation']['summary']['bound']==1
 return len(d['cases'])
if __name__=='__main__':
 if sys.argv[1:]==['--audit']:
  x=json.load(sys.stdin);print(json.dumps(audit(x['request'],x['observation'])))
 elif not sys.argv[1:]:print('PASS '+str(check())+' conditions; literal remaining/placements + exhaustive assignments; no producer import')
 else:print('unsupported argument',file=sys.stderr);sys.exit(2)
